<template><el-container class="sim"><el-header><el-button @click="back">返回健康首页</el-button><strong>{{names[kind]||'模拟器'}}</strong><el-tag type="warning">教学模拟</el-tag></el-header><el-main><el-row :gutter="32"><el-col :xs="24" :md="10"><el-card><template #header>测量信息</template><el-form label-position="top"><el-form-item label="年龄"><el-input-number v-model="form.age" :min="1" :max="120"/></el-form-item><el-form-item label="身高 cm"><el-input-number v-model="form.heightCm" :min="50" :max="250"/></el-form-item><el-form-item label="体重 kg"><el-input-number v-model="form.weightKg" :min="10" :max="350"/></el-form-item><el-form-item v-if="kind==='glucose'" label="测量状态"><el-select v-model="form.mealState"><el-option label="空腹" value="fasting"/><el-option label="餐后" value="postmeal"/></el-select></el-form-item><el-form-item label="BMI">{{bmi}}</el-form-item></el-form><el-button type="primary" :disabled="busy" @click="start">{{busy?'测量中…':'开始测量'}}</el-button><el-button v-if="kind==='sports'" @click="saveSports" :disabled="!elapsed">保存运动记录</el-button><el-button v-if="busy" @click="stop">停止</el-button><el-divider v-if="kind!=='sports'"/><template v-if="kind!=='sports'"><p class="ai-note">也可按上方参数检索Coze合成教学样本。检索回答不作为测量记录入库。</p><el-button :disabled="!aiConfigured" :loading="aiBusy" @click="retrieveSample">检索智能体教学样本</el-button><p v-if="!aiConfigured" class="ai-note">外部智能体当前未启用</p></template></el-card></el-col><el-col :xs="24" :md="14"><el-card><template #header>模拟设备显示屏</template><section class="screen"><template v-if="kind==='sports'"><h1>{{elapsed}}</h1><p>步 · 每秒一步，刷新归零</p></template><template v-else><h1>{{busy?remaining+' 秒':result?'测量完成':'准备就绪'}}</h1><p>数据来源：本地教学模拟</p><svg v-if="kind==='ecg'" viewBox="0 0 600 120"><polyline :points="wave" fill="none" stroke="#57edc1" stroke-width="2"/></svg></template></section><el-descriptions v-if="result" :column="1" border><el-descriptions-item v-for="(v,k) in result" :key="k" :label="labels[k]||k">{{v}}</el-descriptions-item></el-descriptions><el-alert class="notice" title="数据仅供软件课程演示，不能用于诊断或调整用药" type="info" :closable="false"/></el-card></el-col></el-row><el-card v-if="aiAnswer"><template #header>Coze教学样本检索结果</template><pre class="ai-answer">{{aiAnswer}}</pre><el-alert title="这是知识库教学检索回答，不是真实设备测量；不会自动修改上方本地采集结果。" type="info" :closable="false"/></el-card></el-main></el-container></template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {call} from '@/api/health'
const route=useRoute(),router=useRouter(),kind=computed(()=>route.params.kind),form=ref({age:40,heightCm:170,weightKg:65,mealState:'fasting',durationSeconds:60}),result=ref(),busy=ref(false),elapsed=ref(0),remaining=ref(0),aiConfigured=ref(false),aiBusy=ref(false),aiAnswer=ref('');let timer
const names={pressure:'血压计',glucose:'血糖仪',lipid:'血脂仪',ecg:'心电图',sports:'运动手表'},labels={source:'数据来源',bmi:'BMI',message:'说明',systolic:'收缩压 mmHg',diastolic:'舒张压 mmHg',heartRate:'心率 bpm',glucose:'血糖 mmol/L',totalCholesterol:'总胆固醇 mmol/L',triglycerides:'甘油三酯 mmol/L',hdl:'HDL mmol/L',ldl:'LDL mmol/L',durationSeconds:'时长 秒',waveform:'波形样本',mealState:'空腹或餐后'}
const bmi=computed(()=>(form.value.weightKg/(form.value.heightCm/100)**2).toFixed(1)),wave=computed(()=>Array.from({length:120},(_,i)=>`${i*5},${60-[0,2,0,-8,40,-15,0,8,0][(i+elapsed.value)%9]}`).join(' '))
function stop(){clearInterval(timer);timer=null;busy.value=false}
async function finish(){stop();try{result.value=(await call('workflow/simulate/'+kind.value,'post',form.value)).data;ElMessage.success('测量结果已保存')}catch(e){ElMessage.error('保存失败，请重试')}}
function start(){if(!names[kind.value])return;stop();result.value=null;elapsed.value=0;remaining.value=kind.value==='ecg'?60:5;busy.value=true;timer=setInterval(()=>{elapsed.value++;if(kind.value==='sports')return;remaining.value--;if(remaining.value<=0)finish()},1000)}
async function saveSports(){stop();await call('workflow/sports','post',{steps:elapsed.value,durationSeconds:elapsed.value});ElMessage.success('运动记录已保存')}
async function retrieveSample(){aiBusy.value=true;aiAnswer.value='';try{const response=(await call('ai/measurement/'+kind.value,'post',form.value)).data;aiAnswer.value=response.answer}finally{aiBusy.value=false}}
onMounted(async()=>{try{aiConfigured.value=(await call('ai/status')).data.configured}catch{aiConfigured.value=false}})
function back(){stop();router.push('/health-home')}
watch(kind,()=>{stop();elapsed.value=0;result.value=null;aiAnswer.value=''});onBeforeUnmount(stop)
</script>
<style scoped>.sim{min-height:100vh;background:#f1f7f6}.el-header{display:flex;align-items:center;gap:24px;background:white}.el-main{padding:40px 6vw}.screen{background:#153c39;color:#73e8ca;border-radius:24px;padding:40px;text-align:center;min-height:230px}.screen h1{font-size:48px;letter-spacing:3px}.notice{margin-top:20px}.el-card{margin-bottom:24px}.ai-note{font-size:12px;line-height:1.8;color:#687f70}.ai-answer{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;line-height:1.8;font-size:14px}</style>
